example.text:
{
  "type": "object",
  "properties": {
    "company": { "type": "string", "enum": ["openai", "anthropic", "google"] },
    "model":   { "type": "string" },
    "date":    { "type": "string", "description": "YYYY-MM-DD" },
    "input_price_per_1m": { "type": ["number", "null"] }
  },
  "required": ["company", "model", "date", "input_price_per_1m"],
  "additionalProperties": false
}

// 1) 도구 목록 요청
{ "jsonrpc": "2.0", "id": 2, "method": "tools/list" }

// 2) 도구 실행
{ "jsonrpc": "2.0", "id": 3, "method": "tools/call",
  "params": { "name": "search_news", "arguments": { "query": "Haiku 5.5" } } }

// 2026-07-28 규격부터는 요청마다 params._meta에 프로토콜 버전과 클라이언트 정보가 함께 들어간다

// .claude/settings.json
{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Edit|Write",
        "hooks": [
          { "type": "command",
            "command": "\"$CLAUDE_PROJECT_DIR\"/.claude/hooks/protect-files.sh" }
        ]
      }
    ]
  }
}
// protect-files.sh가 exit 2로 끝나면 편집이 막히고, stderr 메시지가 Claude에게 전달된다

messages[0].content = [
  { type: "document", source: { 강의노트.pdf }, citations: { enabled: true } },
  { type: "text", text: "3장의 핵심 정의를 요약해 줘" }
]
→ 응답: 요약 문장마다 citations: [{ cited_text: "원문 문장", 페이지 위치 }]

{
  "name": "think",
  "description": "생각을 정리할 때 사용한다. 새 정보를 가져오거나 데이터를 바꾸지 않고 생각만 기록한다.",
  "input_schema": { "type": "object",
    "properties": { "thought": { "type": "string", "description": "정리할 생각" } },
    "required": ["thought"] }
}

{
  "name": "price-checker",
  "description": "AI 모델 API 가격을 공식 페이지에서 확인한다",
  "url": "https://agents.example.com/price-checker",
  "skills": [{ "id": "check_price", "description": "모델 ID를 받아 현재 가격을 돌려준다" }]
}

tools = [{
  type: "mcp",
  server_url: "https://mcp.example.com",
  allowed_tools: ["search_issues"],   # 필요한 도구만
  require_approval: "always"          # 실행 전 승인
}]

tools = [{
  type: "custom", name: "run_sql",
  description: "읽기 전용 SQL을 실행한다",
  format: { type: "grammar", syntax: "lark", definition: "start: \"SELECT \" ..." }
}]
→ 모델 출력: SELECT name FROM models WHERE company = 'google'

# 나쁨
